from typing import List

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class SuggestsMethods(BaseClient):
    """
    Методы группы 'Саджесты' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("suggests.rapi_getSuggests")
    def rapi_getSuggests(self, sn: str, suggestTypes: List[dict]) -> dict:
        """
        Получение саджестов отдельным запросом
        :param sn: идентификатор диалога. Может быть уином, почтой или id чата
        :param suggestTypes: типы саджестов
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/getSuggests",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"sn": sn, "suggestTypes": suggestTypes},
            },
        )

    @api_version_check(min_version=1)
    @tracer.start_as_current_span("suggests.rapi_getSmartReply")
    def rapi_getSmartReply(self, sn: str, suggestTypes: List[str], msgId: int) -> dict:
        """
        Получение 'умных' ответов
        :param sn: идентификатор диалога. Может быть уином, почтой или id чата
        :param suggestTypes: типы саджестов
        :param msgId: идентификатор сообщения,
        на которое хотим получить smart reply
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/getSmartReply",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {
                    "sn": sn,
                    "suggestTypes": suggestTypes,
                    "msgId": msgId,
                },
            },
        )
